const activeCount = inputs.table_data.filter(r => r.status === 'active').length;
const inactiveCount = totalRecords - activeCount;
const avgScore = (inputs.table_data.reduce((sum, r) => sum + r.score, 0) / totalRecords).toFixed(1);
const maxScore = Math.max(...inputs.table_data.map(r => r.score));
const minScore = Math.min(...inputs.table_data.map(r => r.score));

// Department distribution
const deptMap = {};
inputs.table_data.forEach(r => {
  deptMap[r.department] = (deptMap[r.department] || 0) + 1;
});
const deptList = Object.entries(deptMap).map(([dept, count]) => `- **${dept}**: ${count}`).join('\n');

const statistics = `
# Statistics Report

## Overview
- **Total Records**: ${totalRecords}
- **Active**: ${activeCount}
- **Inactive**: ${inactiveCount}

## Score Analysis
- **Average Score**: ${avgScore}
- **Highest Score**: ${maxScore}
- **Lowest Score**: ${minScore}
- **Range**: ${maxScore - minScore}

## Department Breakdown
${deptList}
`.trim();

